    const smooth = (v) => v.map((_, i) => (v[(i + 11) % 12] + v[i] + v[(i + 1) % 12]) / 3), f1 = (v) => fmt(v, v < 10 ? 1 : 0);
    const norm = (vals, top) => { const mx = top || Math.max(...vals) || 1; return vals.map((v) => Math.max(0, Math.min(1, v / mx))); };
    const tr = (key) => { const s = sig(r, key); return s && !s.waiting && (s.nasa || s.era5) ? `${t("verdict." + s.verdict)} · ${headline(s)}` : ""; };
    const add = (o) => (o.level === 0 && !o.now ? out.none.push(o.id) : out.list.push({ ...o, level: o.level === 0 ? 1 : o.level, why: (o.why || []).filter(Boolean) }));
