      const two = E && Math.abs(E.d50 - A.d50) >= 0.5 ? t("rp.flood.two", { a: fmt(A.d50, 1), b: fmt(E.d50, 1), rec: fmt(E.wet[0], 0), y: E.wet[1] }) : "";
      const wetBy = sum(s50) >= 12 ? s50 : cal.map((c) => c.rain), wetMask = mk(smooth(wetBy), 0, wetBy === s50 ? 0.45 : 0.7);
