    const prev = new Set([...box.querySelectorAll("details[open][data-anchor]")].map((d) => d.dataset.anchor)), fresh = ui.prepFor !== r || !box.querySelector("[data-anchor]"); ui.prepFor = r;
    const isOpen = (a, def) => ((fresh ? def : prev.has(a)) ? "open" : "");
